    {s:7, st:"Ein ANA-Titer ≥ 1:80 ist das obligate Eingangskriterium der ACR/EULAR-Klassifikation des SLE.", c:true, e:"Korrekt – ohne ANA ≥ 1:80 ist per Definition kein SLE klassifizierbar."},
    {s:7, st:"Anti-dsDNA und Anti-Sm gelten als spezifische immunologische Kriterien des SLE.", c:true, e:"Korrekt – beide sind hoch spezifisch und gehen in die immunologische Domäne der Klassifikation ein."},
    {s:7, st:"Beim medikamentös-induzierten SLE sind in über 90 % Anti-Histon-Antikörper positiv.", c:true, e:"Korrekt – Anti-Histon ist der Leitmarker des medikamentös-induzierten SLE (Trigger: Hydralazin, Isoniazid, Minocyclin, TNFα-I)."},
    {s:7, st:"Hydroxychloroquin ist bei begleitender Psoriasis unbedenklich einzusetzen.", c:false, e:"Falsch – Antimalariamittel können eine Psoriasis exazerbieren und sind daher mit Vorsicht einzusetzen."},
    {s:7, st:"Rauchen steigert die Wirksamkeit von Antimalariamitteln beim kutanen Lupus.", c:false, e:"Falsch – Rauchen setzt die Wirkung aller Antimalariamittel deutlich herab; Nikotinkarenz ist essenziell."},
    {s:7, st:"Belimumab ist ein Anti-Interferonrezeptor-(IFNAR-)Antikörper.", c:false, e:"Falsch – Belimumab ist ein Anti-BLyS-Antikörper (B-Zell-Suppression). Anti-IFNAR ist Anifrolumab."},
    {s:7, st:"Beim kutanen Lupus sind die Fingerknöchel typischerweise ausgespart, im Gegensatz zur Dermatomyositis.", c:true, e:"Korrekt – der Lupus spart die Knöchel aus (Erythem dazwischen), während Gottron-Papeln der DM direkt über den Knöcheln sitzen."},
    {s:7, st:"Der subakut kutane Lupus (SCLE) ist in über 80 % Anti-Ro/La-positiv.", c:true, e:"Korrekt – > 80 % zeigen Anti-Ro (SSA) und Anti-La (SSB); SLE-Übergangsrisiko ca. 50 %."},
    {s:7, st:"Der kongenitale AV-Block beim neonatalen Lupus entsteht durch transplazentare mütterliche Anti-Ro-Antikörper.", c:true, e:"Korrekt – passive Übertragung von Anti-Ro/La ab der 16. SSW kann einen kongenitalen AV-Block (1–2 %) verursachen."},
    {s:7, st:"Der Lupus erythematodes tumidus (LET) zeigt eine ausgeprägte Interface-Dermatitis mit epidermaler Beteiligung.", c:false, e:"Falsch – der LET betrifft Dermis/Adnexe mit Muzin OHNE epidermale Beteiligung, es fehlt daher die Interface-Dermatitis."},
    {s:7, st:"Der diskoide Lupus (DLE) ist die häufigste Variante des chronisch kutanen Lupus.", c:true, e:"Korrekt – der DLE macht ca. 80 % der CCLE aus und heilt vernarbend ab."},
    {s:7, st:"Anti-MDA5-assoziierte Dermatomyositis verläuft meist stark myopathisch mit exzellenter Prognose.", c:false, e:"Falsch – Anti-MDA5 ist oft amyopathisch, mit rasch progredienter ILD und schlechter Prognose."},
    {s:7, st:"Anti-TIF1-γ ist bei erwachsenen DM-Patienten mit einem erhöhten Malignomrisiko assoziiert.", c:true, e:"Korrekt – Anti-TIF1-γ begründet ein intensiviertes Tumorscreening bei adulter DM."},
    {s:7, st:"Die juvenile Dermatomyositis ist stark mit Malignomen assoziiert.", c:false, e:"Falsch – die juvenile DM ist NICHT mit Malignomen assoziiert, dafür häufig mit Calcinosis cutis und Kleingefäss-Vaskulitis."},
    {s:7, st:"Anti-Zentromer-Antikörper sind typisch für die diffuse kutane systemische Sklerose.", c:false, e:"Falsch – Anti-Zentromer kennzeichnet die limitierte Form (CREST). Die diffuse Form ist mit Anti-Scl-70 assoziiert."},
    {s:7, st:"Bei der diffusen kutanen SSc ist die interstitielle Lungenerkrankung die häufigste Mortalitätsursache.", c:true, e:"Korrekt – bei der dcSSc überwiegt die ILD (ILD > PAH) als führende Todesursache."},
    {s:7, st:"Anti-RNA-Polymerase-III-Antikörper sind mit der renalen Krise der systemischen Sklerose assoziiert.", c:true, e:"Korrekt – Anti-RNA-Pol III ist mit rasch progredienter Sklerose, renaler Krise und Mamma-Ca-Assoziation verbunden."},
    {s:7, st:"Beim primären Raynaud-Phänomen sind die Nagelfalzkapillaren typischerweise pathologisch verändert.", c:false, e:"Falsch – beim primären Raynaud ist die Kapillarmikroskopie normal; pathologische Megakapillaren sprechen für eine sekundäre Form (SSc/DM)."},
    {s:7, st:"Die eosinophile Fasziitis spart typischerweise Gesicht und Akren aus.", c:true, e:"Korrekt – das symmetrische, teigige Erythem mit Groove-Zeichen betrifft v.a. die Extremitäten unter Aussparung von Gesicht und Akren."},
    {s:7, st:"Die Mischkollagenose (Sharp-Syndrom) ist durch hochtitrige Anti-U1-RNP-Antikörper definiert.", c:true, e:"Korrekt – hochtitrige Anti-U1-RNP definieren die MCTD; die pulmonale Hypertonie ist die schwerste Komplikation."},
    {s:7, st:"Das Sjögren-Syndrom erhöht das Risiko für ein Non-Hodgkin-(MALT-)Lymphom.", c:true, e:"Korrekt – das Risiko für ein MALT-Lymphom ist etwa 20-fach erhöht."},
    {s:7, st:"Die Morphea geht regelhaft mit innerer Organbeteiligung und Raynaud-Phänomen wie die systemische Sklerose einher.", c:false, e:"Falsch – die Morphea ist lokal, ohne Raynaud und ohne Organbeteiligung (Ausnahme lineäre Morphea des Kopfes). Das unterscheidet sie von der SSc."}
